package omtteam.openmodularlighting.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.damagesource.DamageType;
import omtteam.openmodularlighting.OML;

/**
 * Damage types of the mod. They are data-driven; the JSON files are generated by datagen.
 */
public final class ModDamageTypes {
    /** UV light blocks (1.7.10 used cactus damage). Death message {@code death.attack.openmodularlighting.uv_light}. */
    public static final ResourceKey<DamageType> UV_LIGHT = ResourceKey.create(Registries.DAMAGE_TYPE, OML.id("uv_light"));

    private ModDamageTypes() {
    }

    /** Exhaustion 0.1 like cactus damage. */
    public static DamageType uvLight() {
        return new DamageType(OML.MOD_ID + ".uv_light", 0.1F);
    }
}
